CREATE SEQUENCE metadata_restart_sequence START 10;
SELECT nextval('metadata_restart_sequence');
BEGIN;
SAVEPOINT before_restart;
ALTER SEQUENCE metadata_restart_sequence RESTART 50;
SELECT nextval('metadata_restart_sequence');
ROLLBACK TO before_restart;
SELECT nextval('metadata_restart_sequence');
ROLLBACK;
SELECT nextval('metadata_restart_sequence');
COMMENT ON SEQUENCE metadata_restart_sequence IS 'original';
BEGIN;
ALTER SEQUENCE metadata_restart_sequence RENAME TO metadata_renamed_sequence;
COMMENT ON SEQUENCE metadata_renamed_sequence IS 'changed';
SAVEPOINT before_rename;
ALTER SEQUENCE metadata_renamed_sequence RENAME TO metadata_discarded_sequence;
COMMENT ON SEQUENCE metadata_discarded_sequence IS 'discarded';
ROLLBACK TO before_rename;
SELECT obj_description('metadata_renamed_sequence'::regclass, 'pg_class');
ALTER SEQUENCE metadata_renamed_sequence RENAME TO metadata_restart_sequence;
COMMIT;
SELECT obj_description('metadata_restart_sequence'::regclass, 'pg_class');
DROP SEQUENCE metadata_restart_sequence;

CREATE FUNCTION metadata_original_function() RETURNS integer LANGUAGE SQL AS 'SELECT 1';
COMMENT ON FUNCTION metadata_original_function() IS 'original';
BEGIN;
CREATE OR REPLACE FUNCTION metadata_original_function() RETURNS integer LANGUAGE SQL AS 'SELECT 2';
ALTER FUNCTION metadata_original_function() RENAME TO metadata_renamed_function;
SAVEPOINT before_replace;
CREATE OR REPLACE FUNCTION metadata_renamed_function() RETURNS integer LANGUAGE SQL AS 'SELECT 3';
ALTER FUNCTION metadata_renamed_function() RENAME TO metadata_discarded_function;
COMMENT ON FUNCTION metadata_discarded_function() IS 'discarded';
ROLLBACK TO before_replace;
SELECT metadata_renamed_function();
SELECT obj_description('metadata_renamed_function()'::regprocedure, 'pg_proc');
COMMIT;
SELECT metadata_renamed_function();
SELECT obj_description('metadata_renamed_function()'::regprocedure, 'pg_proc');
COMMENT ON FUNCTION metadata_renamed_function() IS 'changed';
SELECT description FROM pg_description WHERE objoid = 'metadata_renamed_function()'::regprocedure;
BEGIN;
DROP FUNCTION metadata_renamed_function();
CREATE FUNCTION metadata_renamed_function() RETURNS integer LANGUAGE SQL AS 'SELECT 9';
COMMENT ON FUNCTION metadata_renamed_function() IS 'replacement';
COMMIT;
SELECT metadata_renamed_function();
SELECT obj_description('metadata_renamed_function()'::regprocedure, 'pg_proc');
DROP FUNCTION metadata_renamed_function();
